import{_ as t,o as a,c as n,a2 as e}from"./chunks/framework.B4hAkGey.js";const g=JSON.parse('{"title":"14.1 基础入门：抖动、乱序与播放平滑","description":"","frontmatter":{},"headers":[],"relativePath":"guide/14-handwritten-jitterbuffer/basics.md","filePath":"guide/14-handwritten-jitterbuffer/basics.md","lastUpdated":1792683941000}'),i={name:"guide/14-handwritten-jitterbuffer/basics.md"};function p(d,s,l,r,o,h){return a(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="_14-1-基础入门-抖动、乱序与播放平滑" tabindex="-1">14.1 基础入门：抖动、乱序与播放平滑 <a class="header-anchor" href="#_14-1-基础入门-抖动、乱序与播放平滑" aria-label="Permalink to &quot;14.1 基础入门：抖动、乱序与播放平滑&quot;">​</a></h1><blockquote><p>网络不是流水线。同一发端以固定间隔发出的 RTP 包，经过路由器队列、多条路径、拥塞丢包后，到达接收端时早已“面目全非”。Jitter Buffer（抖动缓冲区）就是接收端的&quot;整形器&quot;——把乱序的包排好队、把抖动的间隔熨平，让播放端能匀速出帧。</p></blockquote><hr><h2 id="_14-1-1-抖动-jitter-从何而来" tabindex="-1">14.1.1 抖动（Jitter）从何而来 <a class="header-anchor" href="#_14-1-1-抖动-jitter-从何而来" aria-label="Permalink to &quot;14.1.1 抖动（Jitter）从何而来&quot;">​</a></h2><p><strong>Jitter（抖动）</strong> 是指同一数据流中相邻包的到达间隔与发送间隔之间的偏差。它不是&quot;延迟大&quot;，而是<strong>延迟不稳定</strong>。</p><p>三个最常见成因：</p><table tabindex="0"><thead><tr><th>成因</th><th>说明</th><th>典型量级</th></tr></thead><tbody><tr><td><strong>网络队列（Queueing Delay）</strong></td><td>路由器拥塞时把包放进队列，队列长度随流量起伏，导致包与包之间的排队时间不一致</td><td>10~300ms</td></tr><tr><td><strong>多路径（Multipath）</strong></td><td>ECMP 或链路聚合把同一条流的包分到不同路径走，快的包先到、慢的后到</td><td>0~50ms</td></tr><tr><td><strong>拥塞 / 重传（Congestion / Retransmission）</strong></td><td>底层链路层重传、5G HARQ 等都会让个别包&quot;突然晚到&quot;</td><td>50~500ms</td></tr></tbody></table><p>一条看似直通的链路，在微观层面是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发送端：  0ms    20ms   40ms   60ms   80ms   100ms</span></span>
<span class="line"><span>          |      |      |      |      |      |</span></span>
<span class="line"><span>          ▼      ▼      ▼      ▼      ▼      ▼</span></span>
<span class="line"><span>          ▓▓▓    ▓▓▓    ▓▓▓    ▓▓▓    ▓▓▓    ▓▓▓</span></span>
<span class="line"><span>          │      │      │      │      │      │</span></span>
<span class="line"><span>网络：    │      │      │      │      │      │</span></span>
<span class="line"><span>   路由A  ═══════╤══════╧══════╤══════╤══════╧═════</span></span>
<span class="line"><span>   路由B         └─────────────┘      └───────────</span></span>
<span class="line"><span>          │      │      │      │      │      │</span></span>
<span class="line"><span>          ▼      ▼      ▼      ▼      ▼      ▼</span></span>
<span class="line"><span>接收端：  5ms    18ms   62ms   65ms   250ms  105ms</span></span>
<span class="line"><span>          ↑ 前面两个几乎同步到达 ↑   ↑ 中间两个被挤进队列 ↑     ↑ 最后一个被延迟后反超</span></span></code></pre></div><hr><h2 id="_14-1-2-接收端时间-vs-发送端时间" tabindex="-1">14.1.2 接收端时间 vs 发送端时间 <a class="header-anchor" href="#_14-1-2-接收端时间-vs-发送端时间" aria-label="Permalink to &quot;14.1.2 接收端时间 vs 发送端时间&quot;">​</a></h2><p>我们无法让接收端&quot;看到&quot;发送端的时钟，只能把每个包到达本地的时间与包身上携带的 RTP timestamp（发送时刻）做比较。</p><p>定义 <strong>Transit Time（传输耗时）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>transit = arrivalTime - timestamp</span></span></code></pre></div><p>相邻两个包的 transit 之差，就是瞬时抖动：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D(i, i-1) = (arrival_i - timestamp_i) - (arrival_{i-1} - timestamp_{i-1})</span></span>
<span class="line"><span>            = (arrival_i - arrival_{i-1}) - (timestamp_i - timestamp_{i-1})</span></span></code></pre></div><ul><li><code>D &gt; 0</code>：这个包比上一个<strong>晚到得更多</strong>（抖动变大）</li><li><code>D &lt; 0</code>：这个包比上一个<strong>晚到得更少</strong>（抖动变小，甚至后来居上）</li></ul><p>RFC 3550 建议用指数滑动平均来估算抖动 <code>J</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>J = J + (|D| - J) / 16</span></span></code></pre></div><p>这是个非常实用的&quot;记忆曲线&quot;：突发抖动会拉高 J，但很快又会回落。</p><hr><h2 id="_14-1-3-jitter-buffer-的核心任务" tabindex="-1">14.1.3 Jitter Buffer 的核心任务 <a class="header-anchor" href="#_14-1-3-jitter-buffer-的核心任务" aria-label="Permalink to &quot;14.1.3 Jitter Buffer 的核心任务&quot;">​</a></h2><p>接收端把 RTP 包送进 Jitter Buffer 后，Jitter Buffer 要解决三件事：</p><ol><li><p><strong>乱序重排（Reorder）</strong></p><ul><li>包不一定按 <code>seq</code> 号到达。Jitter Buffer 先把所有到达的包按 <code>seq</code> 存进一个有序容器（常用环形缓冲区或 Map），等播放器来取。</li></ul></li><li><p><strong>消除抖动（De-jitter）</strong></p><ul><li>播放器是匀速的（比如每 20ms 取一帧），但网络不是匀速的。Jitter Buffer 用&quot;等待&quot;把早到的包囤起来、让晚到的包能赶上，从而把输出间隔抹平。</li></ul></li><li><p><strong>控制延迟（Latency Control）</strong></p><ul><li>囤得越久，抖动吸收越好，但端到端延迟也越大。Jitter Buffer 必须在&quot;不卡顿&quot;和&quot;低延迟&quot;之间找到一个平衡点。</li></ul></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                      Jitter Buffer                           │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│   乱序到达的 RTP 包                                            │</span></span>
<span class="line"><span>│      seq=5 seq=7 seq=6 seq=4                                 │</span></span>
<span class="line"><span>│       │     │     │     │                                    │</span></span>
<span class="line"><span>│       ▼     ▼     ▼     ▼                                    │</span></span>
<span class="line"><span>│   ┌──────────────────────────┐                               │</span></span>
<span class="line"><span>│   │  Map&lt;seq, Packet&gt;        │  ← 按 seq 重排                 │</span></span>
<span class="line"><span>│   │   4: ✓  5: ✓  6: ✓  7: ✓ │                               │</span></span>
<span class="line"><span>│   └──────────────────────────┘                               │</span></span>
<span class="line"><span>│              │                                               │</span></span>
<span class="line"><span>│              ▼                                               │</span></span>
<span class="line"><span>│   播放器每 20ms 取一帧：seq=4 取出播放 → 等 20ms → seq=5 取出播放 │</span></span>
<span class="line"><span>│   （输出节奏完全匀速）                                          │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="_14-1-4-固定深度-vs-自适应深度的权衡" tabindex="-1">14.1.4 固定深度 vs 自适应深度的权衡 <a class="header-anchor" href="#_14-1-4-固定深度-vs-自适应深度的权衡" aria-label="Permalink to &quot;14.1.4 固定深度 vs 自适应深度的权衡&quot;">​</a></h2><p>最简单的 Jitter Buffer 是<strong>固定深度（Fixed Size）</strong>：播放器始终比最早到达的包慢 <code>N</code> 毫秒（如 200ms）。只要所有包在 200ms 内到达，就不会断粮。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 伪代码：固定深度</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> PLAYOUT_DELAY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ms</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> onTick</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">now</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> target</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> now </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> PLAYOUT_DELAY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> frame</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> findFirstFrameWithTimestampLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(target);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  play</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(frame);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>固定深度的缺陷：</p><table tabindex="0"><thead><tr><th>场景</th><th>问题</th></tr></thead><tbody><tr><td>网络突然变稳定（抖动变小）</td><td>200ms 白白浪费，延迟降不下来</td></tr><tr><td>网络突然恶化（抖动变大）</td><td>200ms 不够，频繁断粮、卡顿</td></tr></tbody></table><p><strong>自适应深度（Adaptive Size）</strong> 的思路是：持续测量历史抖动 <code>J</code>，让目标延迟动态地“尾随”它。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>targetDelay = clamp(baseDelay + k * J, minDelay, maxDelay)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>典型值</th><th>含义</th></tr></thead><tbody><tr><td><code>baseDelay</code></td><td>20~50ms</td><td>留给解码和渲染的保底时间</td></tr><tr><td><code>k</code></td><td>3~5</td><td>抖动要乘几倍才安全</td></tr><tr><td><code>minDelay</code></td><td>40~60ms</td><td>再小就没法平滑了</td></tr><tr><td><code>maxDelay</code></td><td>400~600ms</td><td>再大通话体验就差到不可用了</td></tr></tbody></table><p>WebRTC 的 NetEq 用的就是自适应策略，我们下一节细讲。</p><hr><h2 id="_14-1-5-音频-vs-视频-jitter-buffer-的差异" tabindex="-1">14.1.5 音频 vs 视频 Jitter Buffer 的差异 <a class="header-anchor" href="#_14-1-5-音频-vs-视频-jitter-buffer-的差异" aria-label="Permalink to &quot;14.1.5 音频 vs 视频 Jitter Buffer 的差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>音频（Audio）</th><th>视频（Video）</th></tr></thead><tbody><tr><td><strong>帧大小</strong></td><td>固定（如 20ms Opus 帧）</td><td>可变（I 帧大、P 帧小）</td></tr><tr><td><strong>解码依赖</strong></td><td>通常一帧独立解码</td><td>强依赖前序帧（除非使用 SVC）</td></tr><tr><td><strong>丢失表现</strong></td><td>用 PLC（Packet Loss Concealment）插值，听感稍闷</td><td>画面花屏 / 卡顿</td></tr><tr><td><strong>Buffer 策略</strong></td><td>追求最小延迟（NetEq 甚至做加速/减速播放）</td><td>允许更大深度，重点保流畅</td></tr><tr><td><strong>组装逻辑</strong></td><td>一包一帧，按序播放</td><td>一帧可能分多包（FU-A / STAP-A），需要聚合</td></tr><tr><td><strong>典型深度</strong></td><td>60~150ms</td><td>200~500ms</td></tr></tbody></table><blockquote><p><strong>注意</strong>：WebRTC 在统一框架里分别实现了 <code>NetEq</code>（音频）和 <code>JitterBuffer</code>（视频），它们的底层数据结构类似，但上层控制策略差异很大。14.2 节会重点讲视频侧的帧组装与自适应延迟。</p></blockquote><hr><h2 id="_14-1-6-小结" tabindex="-1">14.1.6 小结 <a class="header-anchor" href="#_14-1-6-小结" aria-label="Permalink to &quot;14.1.6 小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你应该记住</th><th></th></tr></thead><tbody><tr><td><strong>抖动 ≠ 延迟</strong></td><td>抖动是延迟的不稳定性，关键在于相邻包的间隔变化</td></tr><tr><td><strong>transit = arrival - timestamp</strong></td><td>接收端唯一可用的时间差指标</td></tr><tr><td><strong>三大任务</strong></td><td>乱序重排、消除抖动、控制延迟</td></tr><tr><td><strong>固定深度简单但僵化</strong></td><td>适合低抖动场景；生产环境通常用自适应</td></tr><tr><td><strong>音频和视频策略不同</strong></td><td>音频怕延迟，视频怕花屏</td></tr></tbody></table><hr><h2 id="下一节" tabindex="-1">下一节 <a class="header-anchor" href="#下一节" aria-label="Permalink to &quot;下一节&quot;">​</a></h2><p>→ <a href="./advanced">14.2 进阶应用：自适应缓冲与帧组装</a></p>`,45)])])}const k=t(i,[["render",p]]);export{g as __pageData,k as default};
